package org.circus.core;
import java.io.*;import java.nio.file.*;import java.util.*;import java.awt.image.BufferedImage;import javax.imageio.ImageIO;
/** Actual original TY music script, independent PE table and portable future-state checks. */
public final class TyMusicModeAudit {
    private static int checks;private static void check(boolean ok,String why)throws IOException{checks++;if(!ok)throw new IOException(why);}private static String hash(String text)throws IOException{return Binary.sha256(text.getBytes("UTF-8"));}
    private static Set<String> actions(DesktopLegacy e){Set<String> r=new LinkedHashSet<>();for(DesktopEngine.Control c:e.controls())if(!c.action.isEmpty())r.add(c.action);return r;}
    private static void settle(DesktopLegacy e)throws Exception{for(int n=0;n<10000;n++){e.tick(1000);Dc2Host h=e.host();if(e.vm().status()==MesVm.Status.FAULT)throw new IOException(e.vm().error());if(e.menuWaiting())return;if(h.presentationWaiting){e.vm().signalHost(e.ticket(),MesVm.HostSignal.TEXT_COMPLETE);continue;}for(int c=1;c<6;c++)if(e.audioActive(c)&&!e.audioLoop(c))e.audioCompleted(c,e.audioGeneration(c));if(!e.movie().isEmpty())e.vm().signalHost(e.ticket(),MesVm.HostSignal.MEDIA_COMPLETE);if(h.remainingMillis()<0)e.vm().signalHost(e.ticket(),MesVm.HostSignal.ADVANCE);}throw new IOException("TY music menu did not settle");}
    private static void choose(DesktopLegacy e,String action)throws Exception{check(actions(e).contains(action),"Native music action exists: "+action);e.choose(action);settle(e);}
    private static int[] pixels(DesktopLegacy e)throws Exception{BufferedImage im=e.render();try{return im.getRGB(0,0,e.width,e.height,null,0,e.width);}finally{im.flush();}}
    private static Map<String,Object> baked(DesktopLegacy e,CircusResources data,Path out,String name)throws Exception{
        TyHost h=(TyHost)e.host();check(h.scene.slots[1].equals("@ui-capture")&&h.uiCapture!=null&&h.uiCapture.kind==UiCapture.ARGB,"Service9 stores immutable background pixels");int index=e.vm().variables.read(3,5);byte[] exe=data.files.read(data.files.executable,4*1024*1024);Dc2NativeData.Pe pe=new Dc2NativeData.Pe(exe);int at=pe.at(0x4feb98+260*index),end=at;while(exe[end]!=0&&end-at<260)end++;byte[] raw=Arrays.copyOfRange(exe,at,end);String expected=new TextCodec("","","GBK").decode(raw);check(expected.equals(h.musicNames().text(index)),"Selected native PE title matches independent cell read");check(h.musicNames().encoding.equals("GBK"),"Selected translated PE title encoding is independent GBK");
        int[] base=data.image("system/music_back").argb(true),draw=h.uiCapture.pixels().argb;int changed=0;for(int n=0;n<draw.length;n++)if(base[n]!=draw[n]){changed++;int x=n%800,y=n/800;check(x>=79&&x<428&&y>=97&&y<130,"Background changes are limited to the two title draws with platform font bearings");}check(changed>0,"Native title produces visible pixels");
        BufferedImage frame=e.render();try{ImageIO.write(frame,"png",out.resolve(name+".png").toFile());}finally{frame.flush();}return Json.obj("index",index,"title_utf8_sha256",hash(expected),"raw_bytes",raw.length,"modified_background_pixels",changed,"frame_sha256",Binary.sha256(Files.readAllBytes(out.resolve(name+".png"))));
    }
    public static void main(String[] a)throws Exception{
        if(a.length<2||a.length>3)throw new IOException("Require readonly_TY_GAME owned_OUTPUT [--baseline]");boolean baseline=a.length==3&&a[2].equals("--baseline");Path game=Paths.get(a[0]).toRealPath(),out=DesktopRouteAudit.outputOutsideGame(game,a[1]);System.setProperty("dc.saveRoot",out.resolve("saves").toString());System.setProperty("dc.cacheRoot",out.resolve("cache").toString());Map<String,Object> report=Json.obj("original_executable_run",false,"original_game_files_written",false,"media_completion_simulated",true,"scope","Original music menu / selected PE table / immutable background bake and portable restore. No native GDI font-pixel or audible playback equivalence claim.");
        try{GameResources files=new GameResources(new LocalGameStorage(game),"dc2ty_chinese(simplified)_patch.exe");CircusResources data=new CircusResources(files,Profiles.get("dc2ty-5f69"));TextCodec codec=GameText.select(files,data.profile,"auto","");DesktopLegacy e=new DesktopLegacy(data,codec,true);settle(e);choose(e,"02");choose(e,"extra");
            if(baseline){String error="";try{choose(e,"bgm");}catch(IOException failure){error=failure.getMessage();}check(error.contains("music @0x135e")&&error.contains("[9, 0]"),"Old production exactly reproduces reported service9 failure");report.put("error",error);report.put("result","OLD_BEHAVIOR_REPRODUCED");}
            else{
                choose(e,"bgm");check(e.vm().scriptName().equals("music")&&e.menuWaiting(),"Original title/extra/bgm reaches native music wait");report.put("initial",baked(e,data,out,"01-initial"));int[] first=pixels(e),firstBake=e.host().uiCapture.pixels().argb;e.render().flush();check(Arrays.equals(first,pixels(e)),"Repeated render does not bake again or accumulate text");
                choose(e,"music0");report.put("track0_audio",Json.obj("logical",e.host().logicalMusic(),"active",e.audioActive(0),"loop",e.audioLoop(0),"resource",e.audio(0),"fade",e.host().musicFadeRemaining));check(e.host().logicalMusic()==1&&e.audioActive(0)&&!e.audioLoop(0)&&e.audio(0).equals(data.named("music",1)),"First original track is id1 in native default single-play mode");report.put("track0",baked(e,data,out,"02-track0"));check(Arrays.equals(firstBake,e.host().uiCapture.pixels().argb),"Reloading same title gives identical background pixels instead of layering old glyphs");
                choose(e,"music1");check(e.host().logicalMusic()==3&&e.audioActive(0)&&!e.audioLoop(0),"Second original track switches to id3 single play");report.put("track1",baked(e,data,out,"03-track1"));int[] second=pixels(e);check(!Arrays.equals(firstBake,e.host().uiCapture.pixels().argb),"Different music title changes background pixels");byte[] saved=e.snapshot();check(e.host() instanceof TyHost&&((TyHost)e.host()).musicTitleBaker!=null,"Platform baker is bound before snapshot");
                e.restore(saved);check(e.host() instanceof TyHost&&((TyHost)e.host()).musicTitleBaker!=null,"Restored host retains the platform baker");check(Arrays.equals(second,pixels(e)),"Snapshot restores exact baked background and menu pixels");choose(e,"music0");check(e.host().logicalMusic()==1,"Restored owner can bake and select a different track");e.restore(saved);choose(e,"rplay");check(e.host().logicalMusic()==3&&e.audioActive(0)&&e.audioLoop(0),"Original repeat-mode switch selects looping play");
                choose(e,"stop");check(e.host().logicalMusic()==-1&&!e.audioActive(0),"Original Stop stops actual runtime music channel");choose(e,"next");check(e.vm().variables.read(3,8)==1,"Original next-page command advances native page");choose(e,"back");check(e.vm().variables.read(3,8)==0,"Original previous-page command returns page0");choose(e,"return");check(!e.vm().scriptName().equals("music")&&actions(e).contains("bgm"),"Original return reaches Extra");check(!e.host().scene.slots[1].equals("@ui-capture"),"Normal background reload removes native music-name bake");choose(e,"bgm");check(e.vm().variables.read(3,5)==0&&e.menuWaiting(),"Music reentry resets its original selected index");baked(e,data,out,"04-reentry");check(e.missingImages.isEmpty(),"Original menu has no missing images");
                List<Object> tables=new ArrayList<>();for(String exe:new String[]{"DC2TY.EXE","DC2TYC.exe","dc2ty_chinese(simplified)_patch.exe"}){GameResources rf=new GameResources(new LocalGameStorage(game),exe);TyMusicNames names=TyMusicNames.load(new CircusResources(rf,data.profile));List<String> hashes=new ArrayList<>();for(int n=0;n<48;n++){check(!names.text(n).isEmpty(),"All48 reviewed music cells are nonempty");hashes.add(hash(names.text(n)));}tables.add(Json.obj("exe_sha256",names.executableSha256,"table_sha256",names.tableSha256,"encoding",names.encoding,"title_utf8_sha256",hashes));}report.put("native_title_tables",tables);report.put("result","PASS");
            }
        }catch(Exception failure){report.put("result","FAIL");report.put("error",failure.toString());throw failure;}finally{report.put("checks",checks);Files.write(out.resolve("report.json"),(Json.text(report)+"\n").getBytes("UTF-8"));}System.out.println(Json.text(Json.obj("result",report.get("result"),"checks",checks)));
    }
}
